public class StringDemo {
  public static void main(String[] args){
    String username = "Tendulkar";
    int size = username.length();
    if(size > 8 && size < 15){
      char arr[] = username.toCharArray();
      int count = 0;
      for(char c : arr){
        if(Character.isLetter(c)){
          ++count;
        }
      }
      if(count == size){
        System.out.println("valid username");
      }
    }
  }
}

public class StringBufferDemo {
  public static void main(String[] args){
    String firstName = "Sachin";
    String lastName = "Tendulkar";
    String fullName = firstName + lastName;
    System.out.println(fullName); // Creates new String objects

    StringBuffer sb = new StringBuffer(firstName);
    String fName = sb.append(lastName).toString();
    System.out.println(fName); // Appends to the same object
  }
}

